#!/usr/bin/env node
// Bundle MapLibre's worker with Flaxia's on-device tile protocol.
//
// MapLibre's `importScriptInWorkers` evaluates code at runtime, which the
// production CSP blocks (no `unsafe-eval`). Generate a single classic/module
// worker asset instead and point `setWorkerUrl` at it.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const mapLibreWorker = readFileSync(resolve('node_modules/maplibre-gl/dist/maplibre-gl-worker.mjs'), 'utf8')
  .replace(/export\s*\{[^}]*\};?\s*$/, '')
  .replace(/\/\/# sourceMappingURL=.*$/gm, '');
const protocolWorker = readFileSync(resolve('src/lib/maps/protocol-worker.js'), 'utf8');
const out = resolve('public/maplibre-worker.js');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  `// Generated by scripts/build-maplibre-worker.mjs — do not edit.\n${mapLibreWorker}\n${protocolWorker}\n`,
);
console.log(`Generated ${out}`);
